];

let selectedTag = "ALL";
let startIndex = 0;
const visibleCount = 3;

function renderTabs() {
    const tabsWrapper = document.getElementById("tabs");
    tabsWrapper.innerHTML = "";

    // Responsive layout for tabs
    const tabContainer = document.createElement("div");
    tabContainer.className = "grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4";
    tabsWrapper.appendChild(tabContainer);

    tabsData.forEach(tab => {
        const btn = document.createElement("button");
        btn.textContent = tab.label;
        btn.dataset.tag = tab.value;
        btn.className =
            "tab-btn px-4 py-2 rounded-md font-medium transition-all duration-300 w-full";

        if (tab.value === selectedTag) {
            btn.classList.add("border", "border-[#00B8D9]", "text-[#00B8D9]", "font-semibold");
        } else {
            btn.classList.add("text-gray-600", "hover:text-[#00B8D9]");
        }

        btn.addEventListener("click", () => {
            selectedTag = tab.value;
            startIndex = 0;
            renderTabs();
            renderNews();
        });

        tabContainer.appendChild(btn);
    });
}

function renderNews(direction = "next") {
    const container = document.getElementById("news-container");

    // 1. Animate mỗi item biến mất
    const currentItems = Array.from(container.children);
    currentItems.forEach(item => {
        item.classList.add(
            "transition-all",
            "duration-300",
            "ease-in-out",
            "opacity-0",
            direction === "next" ? "-translate-x-8" : "translate-x-8"
        );
    });

    setTimeout(() => {
        const filteredNews =
            selectedTag === "ALL"
                ? newsList
                : newsList.filter(news => news.tag === selectedTag);

        container.innerHTML = "";

        const visibleCount = window.innerWidth < 700 ? 1 : 3;
        const visibleNews = [];
        for (let i = 0; i < visibleCount; i++) {
            if (filteredNews.length > 0) {
                visibleNews.push(filteredNews[(startIndex + i) % filteredNews.length]);
            }
        }

        visibleNews.forEach(news => {
            const item = document.createElement("div");
            item.className =
                "bg-white rounded-xl  transition-all duration-500 ease-in-out transform opacity-0 " +
                (direction === "next" ? "translate-x-8" : "-translate-x-8");

            item.innerHTML = `
                <div class="relative overflow-hidden rounded-xl">
                    <img src="${news.image}" alt="${news.title}"
                        class="w-full h-[250px] object-cover transform transition-transform duration-300 rounded-xl" />
                </div>
                <p class="text-xs mt-3 text-gray-500 font-medium">${news.tag} | ${news.date}</p>
                <p class="mt-1 text-lg pb-2"><strong>${news.title}</strong></p>
                <div class="absolute bottom-0 mt-1 h-1 w-12 bg-[#00B8D9] rounded-full"></div>
            `;
            container.appendChild(item);

            // Trigger animation in
            setTimeout(() => {
                item.classList.remove("translate-x-8", "-translate-x-8", "opacity-0");
                item.classList.add("translate-x-0", "opacity-100");
            }, 30); // delay nhỏ để browser render class đầu tiên
        });

    }, 200); // delay để animation cũ hoàn thành
}
document.getElementById("news-prev").addEventListener("click", () => {
    const filtered = selectedTag === "ALL"
        ? newsList
        : newsList.filter(news => news.tag === selectedTag);
    startIndex = (startIndex - 1 + filtered.length) % filtered.length;
    renderNews("prev");
});

document.getElementById("news-next").addEventListener("click", () => {
    const filtered = selectedTag === "ALL"
        ? newsList
        : newsList.filter(news => news.tag === selectedTag);
    startIndex = (startIndex + 1) % filtered.length;
    renderNews("next");
});
// Khởi tạo
renderTabs();
renderNews();

document.addEventListener('DOMContentLoaded', () => {
  // Dynamic title logic
  const titleText = "Khởi đầu sự nghiệp cùng MBW";
  const words = titleText.split(' ');
  const formattedTitle = words.reduce((acc, word, index) => {
    if (index === words.length - 1) {
      return acc + (index > 0 && index % 4 === 0 ? '<br>' : ' ') + `<span class='text-[#00B8D9]'>${word}</span>`;
    }
    return acc + (index > 0 && index % 4 === 0 ? '<br>' : ' ') + word;
  }, '').trim();
  document.getElementById('dynamic-title').innerHTML = formattedTitle;

  // Populate departments
  const departments = [
    'Tất cả phòng ban',
    'Programing & IT',
    'Marketing',
    'Sales',
    'Design',
    'Customer Service',
    'Human Resources'
  ];

  const departmentSelect = document.querySelector('#departmentSelect');
  departments.forEach(dept => {
    const option = document.createElement('option');
    option.value = dept;
    option.textContent = dept;
    departmentSelect.appendChild(option);
  });

  // Search form and filter logic
  const searchForm = document.querySelector('#searchForm');
  const positionInput = document.querySelector('#positionInput');

  searchForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const position = positionInput.value;
    const department = departmentSelect.value;
    console.log('Searching for:', { position, department });
  });

  // Real-time filter
  const filterJobs = (searchTerm = '', department = 'Tất cả phòng ban') => {
    const jobCards = document.querySelectorAll('.job-card');
    jobCards.forEach(card => {
      const title = card.querySelector('.job-title').textContent.toLowerCase();
      const cardDepartment = card.querySelector('.job-department').textContent;
      const matchesSearch = title.includes(searchTerm.toLowerCase());
      const matchesDepartment = department === 'Tất cả phòng ban' || cardDepartment === department;

      card.style.display = matchesSearch && matchesDepartment ? 'block' : 'none';
    });
  };

  positionInput.addEventListener('input', (e) => {
    filterJobs(e.target.value, departmentSelect.value);
  });

  departmentSelect.addEventListener('change', (e) => {
    filterJobs(positionInput.value, e.target.value);
  });

});

