const jobsPerPage = 6;
let currentPage = 1;

function renderFilters() {
  const departmentFilter = document.getElementById('department-filter');
  const jobTypeFilter = document.getElementById('job-type-filter');
  const locationFilter = document.getElementById('location-filter');
  const experienceFilter = document.getElementById('experience-filter');
  const salaryFilter = document.getElementById('salary-filter');

  function createCheckbox(labelText, value, className = '') {
    const label = document.createElement('label');
    label.className = 'flex items-start gap-2 cursor-pointer';
    label.innerHTML = `
      <input type='checkbox' value="${value}" class="shrink-0 mt-1 rounded border-gray-300 text-green-600 focus:ring-green-500 ${className}">
      <span>${labelText}</span>
    `;
    return label;
  }

  departments.forEach(dep => departmentFilter.appendChild(createCheckbox(dep, dep, 'filter-department')));
  jobTypes.forEach(type => jobTypeFilter.appendChild(createCheckbox(type, type)));
  locations.forEach(loc => locationFilter.appendChild(createCheckbox(loc, loc)));
  experiences.forEach(exp => experienceFilter.appendChild(createCheckbox(exp, exp, 'filter-exp')));
  salaries.forEach(sal => salaryFilter.appendChild(createCheckbox(sal, sal, 'filter-salary')));
}

function renderJobs(filteredJobs = jobs) {
  const jobList = document.getElementById("job-list");
  const totalJobs = filteredJobs.length;
  const totalPages = Math.ceil(totalJobs / jobsPerPage);
  const startIndex = (currentPage - 1) * jobsPerPage;
  const endIndex = startIndex + jobsPerPage;
  const jobsToDisplay = filteredJobs.slice(startIndex, endIndex);

  jobList.innerHTML = "";
  jobsToDisplay.forEach(job => {
    const el = document.createElement("div");
    el.className = "bg-white border border-gray-200 p-6 rounded-lg hover:shadow-lg transition-shadow duration-200";
    el.innerHTML = `
      <div class="text-sm flex shrink mb-2"><div class="border border-gray-300 max-w-fit rounded-lg text-black mb-2 p-2">${job.category}</div><div class="text-sm rounded-lg text-gray-600 p-3 pl-3">${job.time}</div></div>
      <div class="flex justify-between items-center mb-2">
          <h3 class="text-lg font-semibold">${job.title}</h3>
          <button class="bg-green-600 text-white min-w-[116px] px-5 py-2 rounded-md hover:bg-green-700 transition-colors">Ứng tuyển</button>
      </div>
      <div class="text-sm flex text-sm rounded-lg text-gray-600 p-2 pl-2">📍 ${job.location} 💼 ${job.type}  💰  ${job.salary}</div>
    `;
    jobList.appendChild(el);
  });

  updatePagination(totalPages);
}

function updatePagination(totalPages) {
  const paginationContainer = document.getElementById('pagination');
  paginationContainer.innerHTML = '';

  const prevButton = document.createElement('button');
  prevButton.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M15 19l-7-7 7-7" /></svg>';
  prevButton.className = 'px-3 py-1 rounded hover:bg-green-600 hover:text-white';
  prevButton.addEventListener('click', () => {
    if (currentPage > 1) {
      currentPage--;
      filterJobs();
    }
  });
  paginationContainer.appendChild(prevButton);

  for (let i = 1; i <= totalPages; i++) {
    const button = document.createElement('button');
    button.innerText = i;
    button.className = 'px-3 py-1 rounded hover:bg-green-600 hover:text-white';
    button.addEventListener('click', () => {
      currentPage = i;
      filterJobs();
    });
    paginationContainer.appendChild(button);
  }

  const nextButton = document.createElement('button');
  nextButton.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" class="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 5l7 7-7 7" /></svg>';
  nextButton.className = 'px-3 py-1 rounded hover:bg-green-600 hover:text-white';
  nextButton.addEventListener('click', () => {
    if (currentPage < totalPages) {
      currentPage++;
      filterJobs();
    }
  });
  paginationContainer.appendChild(nextButton);
}

function filterJobs() {
  const selectedDepartments = Array.from(document.querySelectorAll('.filter-department:checked')).map(cb => cb.value);
  const selectedExps = Array.from(document.querySelectorAll('.filter-exp:checked')).map(cb => cb.value);

  const filtered = jobs.filter(job => {
    const matchDept = selectedDepartments.length ? selectedDepartments.includes(job.category) : true;
    const matchExp = selectedExps.length ? selectedExps.includes(job.experience) : true;
    return matchDept && matchExp;
  });

  renderJobs(filtered);
}

// Toggle Sidebar (Mobile)
const toggleFilterBtn = document.getElementById("toggleFilter");
const closeFilterBtns = document.querySelectorAll(".close-filter");
const filterSidebar = document.getElementById("filterSidebar");
const filterOverlay = document.getElementById("filterOverlay");

toggleFilterBtn.addEventListener("click", () => {
  filterSidebar.classList.remove("-translate-x-full");
  if (filterOverlay) filterOverlay.classList.remove("hidden");
  document.body.classList.add("overflow-hidden");
});

closeFilterBtns.forEach(btn => {
  btn.addEventListener("click", () => {
    filterSidebar.classList.add("-translate-x-full");
    if (filterOverlay) filterOverlay.classList.add("hidden");
    document.body.classList.remove("overflow-hidden");
  });
});

if (filterOverlay) {
  filterOverlay.addEventListener("click", () => {
    filterSidebar.classList.add("-translate-x-full");
    filterOverlay.classList.add("hidden");
    document.body.classList.remove("overflow-hidden");
  });
}

// Khởi tạo
renderFilters();
renderJobs();

// Gắn sự kiện filter
document.addEventListener('change', (e) => {
  if (e.target.classList.contains('filter-department') || e.target.classList.contains('filter-exp')) {
    currentPage = 1;
    filterJobs();
  }
});

document.addEventListener('DOMContentLoaded', () => {
  // Dynamic title logic
  const titleText = "Khởi đầu sự nghiệp cùng MBW";
  const words = titleText.split(' ');
  const formattedTitle = words.reduce((acc, word, index) => {
    if (index === words.length - 1) {
      return acc + (index > 0 && index % 4 === 0 ? '<br>' : ' ') + `<span class='text-green-700'>${word}</span>`;
    }
    return acc + (index > 0 && index % 4 === 0 ? '<br>' : ' ') + word;
  }, '').trim();
  document.getElementById('dynamic-title').innerHTML = formattedTitle;

  // Populate departments
  const departments = [
    'Tất cả phòng ban',
    'Programing & IT',
    'Marketing',
    'Sales',
    'Design',
    'Customer Service',
    'Human Resources'
  ];

  const departmentSelect = document.querySelector('#departmentSelect');
  departments.forEach(dept => {
    const option = document.createElement('option');
    option.value = dept;
    option.textContent = dept;
    departmentSelect.appendChild(option);
  });

  // Search form and filter logic
  const searchForm = document.querySelector('#searchForm');
  const positionInput = document.querySelector('#positionInput');

  searchForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const position = positionInput.value;
    const department = departmentSelect.value;
    console.log('Searching for:', { position, department });
  });

  // Real-time filter
  const filterJobs = (searchTerm = '', department = 'Tất cả phòng ban') => {
    const jobCards = document.querySelectorAll('.job-card');
    jobCards.forEach(card => {
      const title = card.querySelector('.job-title').textContent.toLowerCase();
      const cardDepartment = card.querySelector('.job-department').textContent;
      const matchesSearch = title.includes(searchTerm.toLowerCase());
      const matchesDepartment = department === 'Tất cả phòng ban' || cardDepartment === department;

      card.style.display = matchesSearch && matchesDepartment ? 'block' : 'none';
    });
  };

  positionInput.addEventListener('input', (e) => {
    filterJobs(e.target.value, departmentSelect.value);
  });

  departmentSelect.addEventListener('change', (e) => {
    filterJobs(positionInput.value, e.target.value);
  });

});

