        benefits: ["Lương cạnh tranh", "15 ngày phép", "BHXH", "Xe đưa đón", "Cơ hội thăng tiến"]
    },
    // 👇 thêm nhiều job liên quan để kiểm thử
    ...Array.from({ length: 12 }, (_, i) => ({
        title: `Frontend Developer ${i + 1}`,
