    }))
];

renderJobDetail(jobDataList[0]);

// --- Việc làm liên quan có phân trang ---
let relatedJobsRendered = 0;
const JOBS_PER_PAGE = 6;

function renderRelatedJobsPaginated(jobs) {
    const container = document.getElementById("related-jobs-list");
    const loadMoreBtn = document.getElementById("load-more-btn");

    // Trừ job đầu tiên (đã hiển thị ở phần chi tiết)
    const related = jobs.slice(1);
    const nextJobs = related.slice(relatedJobsRendered, relatedJobsRendered + JOBS_PER_PAGE);

    nextJobs.forEach(job => {
        const jobCard = document.createElement("div");
        jobCard.className = "bg-white border border-gray-200 rounded-lg shadow-md p-4 hover:shadow-xl transition";
        jobCard.innerHTML = `
      <h3 class="font-semibold text-gray-900 mb-2">${job.title}</h3>
      <p class="text-sm text-gray-500 mb-1">📍 ${job.location}</p>
      <p class="text-sm text-gray-500 mb-1">💼 ${job.type}</p>
      <p class="text-sm text-gray-500 mb-3">💰 ${job.salary}</p>
    `;
        container.appendChild(jobCard);
    });

    relatedJobsRendered += JOBS_PER_PAGE;

    // Hiện nút "Xem thêm" nếu còn job
    if (relatedJobsRendered < related.length) {
        loadMoreBtn.classList.remove("hidden");
    } else {
        loadMoreBtn.classList.add("hidden");
    }
}

document.getElementById("load-more-btn").addEventListener("click", () => {
    renderRelatedJobsPaginated(jobDataList);
});

// Gọi lần đầu
renderRelatedJobsPaginated(jobDataList);

