/* ===== ONBOARDING STYLES - PHẦN MỚI ===== */

/* Container và transitions */
#container {
  transition: opacity 0.3s ease;
}

/* Onboarding Summary */
#onboarding-summary {
  background: linear-gradient(135deg, #f8f9fa, #ffffff);
  border-left: 4px solid #28a745;
}

/* Progress Circle */
#progress-circle {
  transition: stroke-dashoffset 0.6s ease-in-out;
  filter: drop-shadow(0 2px 4px rgba(40, 167, 69, 0.2));
}

#progress-percentage {
  font-weight: 700;
  color: #2c3e50;
}

/* Onboarding Steps */
.onboarding-step {
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.onboarding-step:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.15);
}

.onboarding-step::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: linear-gradient(180deg, #3498db, #2980b9);
  opacity: 0;
  transition: opacity 0.3s ease;
}

.onboarding-step:hover::before {
  opacity: 1;
}

/* Step Icon */
.step-icon {
  transition: all 0.3s ease;
  position: relative;
  z-index: 2;
}

.step-icon::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 0;
  height: 0;
  background: rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  transform: translate(-50%, -50%);
  transition: all 0.3s ease;
}

.onboarding-step:hover .step-icon::after {
  width: 100%;
  height: 100%;
}

/* Step Status Badges */
.step-status {
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.step-status::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
  transition: left 0.6s ease;
}

.onboarding-step:hover .step-status::before {
  left: 100%;
}

/* File Upload Styles */
.upload-area {
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.upload-area::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(135deg, rgba(59, 130, 246, 0.05), rgba(37, 99, 235, 0.05));
  opacity: 0;
  transition: opacity 0.3s ease;
}

.upload-area:hover::before {
  opacity: 1;
}

.upload-area:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 25px rgba(59, 130, 246, 0.15);
  border-color: #3b82f6;
}

/* Drag states */
.upload-area.drag-over {
  border-color: #3b82f6 !important;
  background-color: #dbeafe !important;
  transform: scale(1.02);
}

.upload-area.drag-over .upload-icon i {
  transform: scale(1.1);
  color: #3b82f6;
}

/* Browse button */
.browse-btn {
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.browse-btn::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
  transition: left 0.6s ease;
}

.browse-btn:hover::before {
  left: 100%;
}

.browse-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 4px 15px rgba(37, 99, 235, 0.3);
}

/* File Preview Area */
.file-preview-area {
  animation: slideInUp 0.4s ease;
  background: linear-gradient(135deg, #ebf8ff, #f0f9ff);
  border: 2px solid #3b82f6;
}

@keyframes slideInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

/* File icon animations */
.file-icon i {
  transition: all 0.3s ease;
}

.file-preview-area:hover .file-icon i {
  transform: scale(1.1) rotate(5deg);
}

/* Progress Bar */
.upload-progress {
  animation: fadeIn 0.3s ease;
}

.upload-progress-bar {
  transition: width 0.3s ease;
  background: linear-gradient(90deg, #3b82f6, #1d4ed8);
  position: relative;
  overflow: hidden;
}

.upload-progress-bar::after {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.3), transparent);
  animation: progressShine 1.5s infinite;
}

@keyframes progressShine {
  0% { left: -100%; }
  100% { left: 100%; }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

/* Uploaded File Success */
.uploaded-file-info {
  animation: successPulse 0.6s ease;
  background: linear-gradient(135deg, #dcfce7, #f0fdf4);
  border: 2px solid #22c55e;
}

@keyframes successPulse {
  0% {
    opacity: 0;
    transform: scale(0.9);
  }
  50% {
    transform: scale(1.05);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}

.uploaded-icon i {
  animation: checkBounce 0.6s ease;
}

@keyframes checkBounce {
  0%, 20%, 60%, 100% {
    transform: translateY(0);
  }
  40% {
    transform: translateY(-10px);
  }
  80% {
    transform: translateY(-5px);
  }
}

/* Action Buttons */
.mark-complete-btn {
  background: linear-gradient(135deg, #22c55e, #16a34a);
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.mark-complete-btn::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.2), transparent);
  transition: left 0.6s ease;
}

.mark-complete-btn:hover::before {
  left: 100%;
}

.mark-complete-btn:hover {
  background: linear-gradient(135deg, #16a34a, #15803d);
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(34, 197, 94, 0.3);
}

/* Upload and Remove buttons */
.upload-btn {
  background: linear-gradient(135deg, #22c55e, #16a34a);
  transition: all 0.3s ease;
}

.upload-btn:hover {
  background: linear-gradient(135deg, #16a34a, #15803d);
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(34, 197, 94, 0.3);
}

.remove-file-btn {
  transition: all 0.3s ease;
}

.remove-file-btn:hover {
  background: #fecaca;
  transform: scale(1.1);
}

/* HR Approval and Completed Info */
.hr-approval-info {
  animation: pulseYellow 2s infinite;
}

@keyframes pulseYellow {
  0%, 100% {
    box-shadow: 0 0 0 0 rgba(245, 158, 11, 0.4);
  }
  50% {
    box-shadow: 0 0 0 10px rgba(245, 158, 11, 0);
  }
}

.step-completed-info {
  animation: fadeInScale 0.5s ease;
}

@keyframes fadeInScale {
  from {
    opacity: 0;
    transform: scale(0.8);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

/* Loading animations */
.fa-spinner {
  animation: spin 1s linear infinite;
}

@keyframes spin {
  to {
    transform: rotate(360deg);
  }
}

/* Jobs Section */
#jobs-section {
  background: linear-gradient(135deg, #f8fafc, #ffffff);
  border-radius: 12px;
  padding: 2rem;
  margin-top: 2rem;
}

/* Responsive Design */
